insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$stance-hold-mirror$boxer$, $boxer$Mirror Stance Hold$boxer$, ARRAY[$boxer$Stand facing a full-length mirror with feet shoulder-width apart.$boxer$, $boxer$Step your lead foot forward and your rear foot back about one shoulder-width, rear foot turned out roughly 45 degrees.$boxer$, $boxer$Bend your knees slightly and settle your weight onto the balls of both feet, posture tall.$boxer$, $boxer$Raise your hands to guard and hold the position for 60 seconds without shifting your feet.$boxer$, $boxer$Check the mirror: hips and shoulders half-turned to the target, not fully square and not fully sideways.$boxer$, $boxer$Rest 30 seconds and repeat for 3 holds, resetting your feet from scratch each time.$boxer$]::text[], $boxer$3 x 60-second holds$boxer$, ARRAY[$boxer$Tall spine, chin tucked, eyes level — don't crouch to feel stable$boxer$, $boxer$Weight balanced and ready to move either direction, not planted$boxer$, $boxer$Breathe normally; tension in the shoulders means you're forcing it$boxer$]::text[], ARRAY[$boxer$square-stance$boxer$, $boxer$weight-forward$boxer$, $boxer$weight-back$boxer$]::text[], $boxer$beginner$boxer$, $boxer$mirror$boxer$, $boxer$stance$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$tape-line-reset$boxer$, $boxer$Tape Line Stance Reset$boxer$, ARRAY[$boxer$Lay two strips of tape on the floor, parallel, about shoulder-width apart.$boxer$, $boxer$Start in your stance with each foot on its line.$boxer$, $boxer$Step-drag forward three steps, keeping each foot tracking along its own line.$boxer$, $boxer$Step-drag back to the start, then step-drag laterally left and right the same way.$boxer$, $boxer$After every direction change, freeze and check: feet back on the lines, stance width unchanged.$boxer$, $boxer$Work for 3 minutes, resetting to the taped stance whenever your feet drift.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$The step-drag keeps your base identical after every move$boxer$, $boxer$If your feet leave the lines, your steps are too big$boxer$, $boxer$Finish every movement in a stance you could punch from$boxer$]::text[], ARRAY[$boxer$square-stance$boxer$, $boxer$wide-stance$boxer$, $boxer$crossing-feet$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$stance$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$balance-push-test$boxer$, $boxer$Partner Balance Push Test$boxer$, ARRAY[$boxer$Take your boxing stance; a partner stands in front of you.$boxer$, $boxer$The partner gives your lead shoulder a firm, slow push — a steady press, not a shove.$boxer$, $boxer$Absorb it without stepping, hopping, or straightening your legs.$boxer$, $boxer$Repeat with pushes to the rear shoulder and to each side.$boxer$, $boxer$If you lose balance, adjust your stance (usually: sink lower, weight centered) and try again.$boxer$, $boxer$Do 30 seconds of pushes from each of the four directions.$boxer$]::text[], $boxer$4 x 30 seconds (one per direction)$boxer$, ARRAY[$boxer$A good stance absorbs pressure; a bad one topples or bounces$boxer$, $boxer$Knees stay soft and springy, never locked$boxer$, $boxer$If you consistently fall forward, your weight is too far over your lead foot$boxer$]::text[], ARRAY[$boxer$stance-drifts$boxer$, $boxer$weight-forward$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$stance$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$stance-with-punches$boxer$, $boxer$Slow 1-2 Stance Check$boxer$, ARRAY[$boxer$Face a partner or mirror in your stance.$boxer$, $boxer$Throw a slow jab-cross at half speed, then freeze fully at the end of the cross.$boxer$, $boxer$Check your feet: same stance width and angles as before the punches, weight centered.$boxer$, $boxer$Return to guard slowly, then repeat — 10 reps, then switch to a slow 1-2-3.$boxer$, $boxer$Have the partner call out any foot that lifted, slid, or turned during the punches.$boxer$, $boxer$Finish with 1 minute of continuous slow 1-2s, freezing at random on the partner's clap.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$Punches should not move your foundation; power comes through it, not from leaving it$boxer$, $boxer$Rear foot pivots on the cross but stays grounded — no lifting$boxer$, $boxer$If your stance widens every combo, you're pushing off instead of rotating$boxer$]::text[], ARRAY[$boxer$square-stance$boxer$, $boxer$weight-forward$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$stance$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$three-minute-stance$boxer$, $boxer$Three-Minute Stance Discipline$boxer$, ARRAY[$boxer$Set a timer for one 3-minute round and take your stance.$boxer$, $boxer$Every 30 seconds, throw a crisp 1-2-3 combination and immediately reset to your exact starting stance.$boxer$, $boxer$Between combinations, make small step-drag adjustments only — never stand up or widen out to rest.$boxer$, $boxer$In the final minute, add pivots after each combination while keeping the stance intact.$boxer$, $boxer$When the round ends, note when your legs wanted to quit: that's the habit to train out.$boxer$, $boxer$Build to 3 full rounds with 1-minute rests.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Fatigue reveals stance flaws — this drill trains the stance to survive them$boxer$, $boxer$Rest by narrowing slightly and breathing, never by standing tall$boxer$, $boxer$Your guard and stance are one system; both must last the round$boxer$]::text[], ARRAY[$boxer$stance-drifts$boxer$, $boxer$weight-back$boxer$]::text[], $boxer$advanced$boxer$, $boxer$none$boxer$, $boxer$stance$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$snap-back-guard$boxer$, $boxer$Jab Snap-Back in the Mirror$boxer$, ARRAY[$boxer$Face a mirror in your stance at jab range from your reflection.$boxer$, $boxer$Throw a slow, full-extension jab, watching your lead hand travel straight out and back.$boxer$, $boxer$Snap the hand back along the exact same path to your cheek — as fast as it went out.$boxer$, $boxer$Freeze for one beat with the glove touching your cheekbone and check: rear hand never moved.$boxer$, $boxer$Repeat for 2 minutes, then do 1 minute where every third jab is a double jab, both hands returning cleanly.$boxer$, $boxer$Finish with 30 seconds of full-speed jabs, guard return still instant.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$The punch is only half the technique; the return is the other half$boxer$, $boxer$A lazy return after the jab is the most common way beginners get countered$boxer$, $boxer$Elbow stays tucked on the return, not flared out$boxer$]::text[], ARRAY[$boxer$drops-guard-on-jab$boxer$, $boxer$hands-low$boxer$]::text[], $boxer$beginner$boxer$, $boxer$mirror$boxer$, $boxer$guard$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$chin-ball-shadowbox$boxer$, $boxer$Tennis Ball Chin Shadowboxing$boxer$, ARRAY[$boxer$Tuck a tennis ball (or rolled-up sock) under your chin, holding it against your chest with your jaw.$boxer$, $boxer$Shadowbox for 2 minutes: jabs, crosses, hooks, footwork — everything.$boxer$, $boxer$If the ball drops, stop, reset it, and continue; count your drops.$boxer$, $boxer$Round two: add head movement — slips and rolls — without losing the ball.$boxer$, $boxer$Goal is zero drops by the third session, not the first.$boxer$, $boxer$Finish with 1 minute of fast combinations, chin still pinned down.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$Chin down, eyes up — you watch the opponent over your guard, not from under it$boxer$, $boxer$A lifting chin when punching is a knockout invitation$boxer$, $boxer$Keep the jaw relaxed; clenching the ball creates shoulder tension$boxer$]::text[], ARRAY[$boxer$chin-up$boxer$, $boxer$hands-low$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$guard$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$guard-check-freeze$boxer$, $boxer$Freeze Guard Check$boxer$, ARRAY[$boxer$Shadowbox freely while a partner watches (or set a timer to beep every 20 seconds).$boxer$, $boxer$On the call or beep, freeze instantly — mid-punch, mid-step, wherever you are.$boxer$, $boxer$Check three things: knuckles at cheekbone height, elbows touching your ribs, chin tucked.$boxer$, $boxer$Score yourself: 3/3 is a pass; anything less, do 10 push-ups and continue.$boxer$, $boxer$Work for 3 minutes; the freezes should catch you in honest positions, not posed ones.$boxer$, $boxer$Advanced version: partner calls freeze only right after your combinations, when guards sag most.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Your guard at the freeze is your real guard — the rest is wishful thinking$boxer$, $boxer$Elbows protect the body; flared elbows open the ribs and telegraph fatigue$boxer$, $boxer$Gloves cover the chin, not the eyes — you must see through your guard$boxer$]::text[], ARRAY[$boxer$hands-low$boxer$, $boxer$elbows-out$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$guard$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$towel-elbow-pin$boxer$, $boxer$Towel Pin Elbow Drill$boxer$, ARRAY[$boxer$Fold a small towel and wedge it between your rear upper arm and your ribs.$boxer$, $boxer$Throw slow crosses for 2 minutes without letting the towel fall.$boxer$, $boxer$The cross must come from hip and shoulder rotation — if your elbow wings out, the towel drops.$boxer$, $boxer$Switch the towel to the lead side and throw slow lead hooks the same way.$boxer$, $boxer$Final minute: alternate cross and lead hook, towel pinned on each side in turn.$boxer$, $boxer$When you can do 3 minutes clean, the elbow discipline is becoming automatic.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$Elbows-out on the cross bleeds power and opens your body$boxer$, $boxer$Rotate the torso to deliver the punch, don't reach with the arm$boxer$, $boxer$Rear hand returns to the cheek every time — the towel only tests the elbow$boxer$]::text[], ARRAY[$boxer$elbows-out$boxer$, $boxer$drops-guard-on-cross$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$guard$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$shell-coverage$boxer$, $boxer$Shell Coverage Under Taps$boxer$, ARRAY[$boxer$Take a high guard: gloves at temples/forehead, elbows tight to the body, chin tucked.$boxer$, $boxer$A partner wearing gloves taps lightly at your guard — head, sides, body — for 60 seconds.$boxer$, $boxer$Don't punch back; just maintain the shell, keep your eyes open, and breathe.$boxer$, $boxer$Between taps, the partner occasionally pauses — don't drop your hands in the pause.$boxer$, $boxer$Rest 30 seconds and repeat for 4 rounds, with the partner varying speed and angle.$boxer$, $boxer$Final round: you may step and pivot while shelling, but the coverage never opens.$boxer$]::text[], $boxer$4 x 60 seconds$boxer$, ARRAY[$boxer$Eyes open and breathing — beginners hold their breath and look away$boxer$, $boxer$A tight shell is forearms and gloves, not hunched shoulders$boxer$, $boxer$The pause is the test: tired fighters drop their hands the moment pressure stops$boxer$]::text[], ARRAY[$boxer$hands-low$boxer$, $boxer$dropping-hands-under-pressure$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$guard$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$guard-on-the-move$boxer$, $boxer$Guard Integrity Footwork Round$boxer$, ARRAY[$boxer$Set a 3-minute timer. You'll move continuously — no punching in this drill.$boxer$, $boxer$Step-drag forward, back, and laterally; add pivots and direction changes on your own rhythm.$boxer$, $boxer$Your gloves do not leave your cheekbones for the entire round — not during pivots, not during quick steps.$boxer$, $boxer$A partner randomly calls single punches ('jab!', 'hook!'); mime the block or parry and snap straight back to guard.$boxer$, $boxer$If a glove drops below chin level at any point, restart the round.$boxer$, $boxer$Build to 3 consecutive clean rounds.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Footwork and guard are trained together because they fail together$boxer$, $boxer$Fast feet make hands lazy — this drill breaks that link$boxer$, $boxer$The mime-block must be small; big defensive motions open bigger holes$boxer$]::text[], ARRAY[$boxer$hands-low$boxer$, $boxer$dropping-hands-under-pressure$boxer$]::text[], $boxer$advanced$boxer$, $boxer$none$boxer$, $boxer$guard$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$wall-jab-range$boxer$, $boxer$Wall Jab Range Finder$boxer$, ARRAY[$boxer$Stand facing a wall at full arm's length plus one fist — mark the spot with tape.$boxer$, $boxer$Throw slow jabs at a small target on the wall (a taped X at chin height).$boxer$, $boxer$The jab must land with a fully extended arm while your torso stays upright — no leaning in.$boxer$, $boxer$If you can't reach without leaning, you're too far: adjust your starting distance, not your posture.$boxer$, $boxer$Do 3 minutes of slow jabs, then 1 minute stepping in with the jab and stepping back out.$boxer$, $boxer$Your head should finish every jab exactly where it started.$boxer$]::text[], $boxer$4 x 1-minute segments$boxer$, ARRAY[$boxer$Overreaching shifts your weight past your lead foot and kills your balance$boxer$, $boxer$The shoulder extends to deliver the jab; the spine stays stacked$boxer$, $boxer$Judge distance with the jab — it's your measuring stick, not a lunge$boxer$]::text[], ARRAY[$boxer$overreaching-jab$boxer$, $boxer$falling-in$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$step-jab-entry$boxer$, $boxer$Step-In Jab Timing$boxer$, ARRAY[$boxer$Start in your stance, well out of jab range from a heavy bag or wall target.$boxer$, $boxer$Step-drag forward and let the jab land at the exact moment your lead foot plants.$boxer$, $boxer$Step back out to your starting spot; reset fully.$boxer$, $boxer$Repeat for 2 minutes slow, focusing on the foot-hand landing sync.$boxer$, $boxer$Next 2 minutes: vary it — sometimes step in without punching (feint the entry), sometimes double up the jab on the step.$boxer$, $boxer$The punch and the step are one movement, not two stacked together.$boxer$]::text[], $boxer$2 x 2-minute rounds$boxer$, ARRAY[$boxer$Landing the punch as the foot plants puts your body weight behind it$boxer$, $boxer$Stepping then punching is late; punching then stepping is a reach — sync them$boxer$, $boxer$Keep the rear hand glued to your cheek through the entire entry$boxer$]::text[], ARRAY[$boxer$overreaching-jab$boxer$, $boxer$arm-punching$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$cross-pivot-freeze$boxer$, $boxer$Cross Pivot Freeze in the Mirror$boxer$, ARRAY[$boxer$Face a mirror in your stance.$boxer$, $boxer$Throw a slow cross: pivot the rear foot, rotate the hips, then the shoulders, arm extending last.$boxer$, $boxer$Freeze at full extension for 2 seconds and check the mirror: rear heel turned, hips and shoulders rotated, chin behind the lead shoulder.$boxer$, $boxer$Slowly retract along the same path; rear hand returns to the cheek.$boxer$, $boxer$Do 10 slow reps, then 1 minute of continuous slow crosses with a freeze every fifth one.$boxer$, $boxer$Finish with 30 seconds at moderate speed — the rotation pattern must survive the speed.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$Power travels ground to fist: foot pivot, hip turn, shoulder turn, then arm$boxer$, $boxer$An arm-only cross is a push — rotation is what makes it a punch$boxer$, $boxer$The chin stays down through the whole rotation; lifting it is the classic cross mistake$boxer$]::text[], ARRAY[$boxer$no-hip-rotation$boxer$, $boxer$arm-punching$boxer$]::text[], $boxer$beginner$boxer$, $boxer$mirror$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$hook-geometry-mirror$boxer$, $boxer$Lead Hook Geometry$boxer$, ARRAY[$boxer$Face a mirror in your stance, lead side toward the mirror.$boxer$, $boxer$Throw a slow lead hook: pivot the lead foot, rotate the hips, arm bent at roughly 90 degrees.$boxer$, $boxer$Freeze at the contact point — check: elbow level with the fist, shoulder touching your chin, rear glove still on your cheek.$boxer$, $boxer$The punch travels on a tight arc, ending in front of your own chin line — never swung wide past it.$boxer$, $boxer$Do 10 slow reps, then 2 minutes of slow hooks with full freezes.$boxer$, $boxer$If your elbow drops below your fist, shorten the arc until the 90-degree bend holds.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$A 90-degree elbow keeps the hook short, fast, and structurally strong$boxer$, $boxer$The lead shoulder ends at the chin — it becomes part of your guard$boxer$, $boxer$Wide looping hooks are slow and visible; tight hooks land first$boxer$]::text[], ARRAY[$boxer$elbow-flare$boxer$, $boxer$dropping-rear-hand-on-hook$boxer$]::text[], $boxer$beginner$boxer$, $boxer$mirror$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$dip-uppercut$boxer$, $boxer$Dip-and-Drive Uppercut$boxer$, ARRAY[$boxer$Stand in your stance in front of a mirror or bag.$boxer$, $boxer$Bend your knees 3-4 inches — a small dip, not a squat — keeping your back straight and chin down.$boxer$, $boxer$Drive upward: legs extend, hips rotate, and the punch travels straight up the center line, palm facing up.$boxer$, $boxer$The power comes from the leg drive and rotation; the arm just delivers it.$boxer$, $boxer$Freeze at the top: fist at chin height of an imaginary opponent, elbow still bent, other hand on your cheek.$boxer$, $boxer$Do 3 x 1-minute rounds alternating lead and rear uppercuts, slow first round, moderate after.$boxer$]::text[], $boxer$3 x 1-minute rounds$boxer$, ARRAY[$boxer$No dip, no uppercut — arm-only uppercuts have nothing behind them$boxer$, $boxer$Keep the punch tight to your center; wide uppercuts miss and expose you$boxer$, $boxer$Don't drop the punching hand before throwing — that's a telegraph, not a wind-up$boxer$]::text[], ARRAY[$boxer$arm-punching$boxer$, $boxer$no-hip-rotation$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$one-two-freeze$boxer$, $boxer$1-2 Freeze Balance Check$boxer$, ARRAY[$boxer$In your stance, throw a 1-2 at half speed and freeze with the cross fully extended.$boxer$, $boxer$Hold 2 seconds and audit: weight centered between the feet, head behind the lead shoulder, rear foot pivoted but grounded.$boxer$, $boxer$Slowly return to stance; repeat 10 times.$boxer$, $boxer$Next round: have a partner watch for telegraphs — shoulder dips, hand pulls, weight shifts before the punches.$boxer$, $boxer$Eliminate one telegraph at a time: the 1-2 should look identical to your guard until the punches fire.$boxer$, $boxer$Finish with 1 minute of continuous 1-2s at moderate speed, freezing on a random clap.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$If you're off balance at the freeze, the punches were thrown with a lunge, not rotation$boxer$, $boxer$Telegraphs are habits, not necessities — film yourself if no partner is available$boxer$, $boxer$Every punch starts and ends in the same stance; the stance is home base$boxer$]::text[], ARRAY[$boxer$falling-in$boxer$, $boxer$telegraphing$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$hook-off-the-jab-bag$boxer$, $boxer$Hook Off the Jab (Heavy Bag)$boxer$, ARRAY[$boxer$Work the heavy bag at jab range for a 3-minute round.$boxer$, $boxer$Every combination starts with a jab; the lead hook follows it — jab-hook, jab-jab-hook.$boxer$, $boxer$The hook must pivot the lead foot and rotate the hips — no arm swings.$boxer$, $boxer$After each hook, the hand snaps back to the cheek before anything else happens.$boxer$, $boxer$Round two: add the cross between them — jab-cross-hook — keeping the same hip rotation on every punch.$boxer$, $boxer$Count clean hooks per round; raise the count each session without losing form.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$The jab occupies the guard; the hook exploits the opening it creates$boxer$, $boxer$Hook power is hip rotation, not arm speed — pivot hard on the lead foot$boxer$, $boxer$Return the hook to the cheek fast; the follow-through is where counters land$boxer$]::text[], ARRAY[$boxer$no-hip-rotation$boxer$, $boxer$single-punches-only$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$power-ladder-singles$boxer$, $boxer$Single-Punch Power Ladder$boxer$, ARRAY[$boxer$Face the heavy bag in your stance.$boxer$, $boxer$Throw ONE jab with full technique — step, rotation, snap — then fully reset to stance.$boxer$, $boxer$Throw ONE cross with full rotation and pivot, then reset.$boxer$, $boxer$Continue through lead hook, rear hook, lead uppercut, rear uppercut: 10 perfect singles each.$boxer$, $boxer$Rest 1 minute, then repeat the ladder at slightly higher speed — technique must not decay.$boxer$, $boxer$If a punch feels weak, slow down: this drill rewards mechanics, not output.$boxer$]::text[], $boxer$2 ladders of 60 punches$boxer$, ARRAY[$boxer$Isolating single punches exposes which ones are arm punches in disguise$boxer$, $boxer$The full reset between punches builds the habit of returning to stance$boxer$, $boxer$Power is technique expressed fast — earn the speed with clean slow reps first$boxer$]::text[], ARRAY[$boxer$arm-punching$boxer$, $boxer$no-hip-rotation$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$double-end-timing$boxer$, $boxer$Double-End Bag Timing$boxer$, ARRAY[$boxer$Work the double-end bag for 3-minute rounds.$boxer$, $boxer$Punch the bag as it rebounds toward you — meet it, don't chase it.$boxer$, $boxer$Focus on snap: fist out and back in a blink, faster than the bag's return.$boxer$, $boxer$Throw only when the timing is right; waiting for the moment is part of the drill.$boxer$, $boxer$Add slips: after each combination, slip the imaginary counter as the bag comes back.$boxer$, $boxer$Build from 2 rounds to 4 as your timing sharpens.$boxer$]::text[], $boxer$4 x 3-minute rounds$boxer$, ARRAY[$boxer$The double-end bag punishes pushing — only snapped punches control it$boxer$, $boxer$Timing beats speed; a well-timed punch lands while a fast wild one misses$boxer$, $boxer$Keep your eyes on the bag through the whole exchange, especially while slipping$boxer$]::text[], ARRAY[$boxer$no-snap$boxer$, $boxer$telegraphing$boxer$]::text[], $boxer$advanced$boxer$, $boxer$bag$boxer$, $boxer$punch-mechanics$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$step-drag-basics$boxer$, $boxer$Step-Drag in Four Directions$boxer$, ARRAY[$boxer$Take your stance in the center of your space.$boxer$, $boxer$Move forward: step with the lead foot first, then drag the rear foot up to restore stance width.$boxer$, $boxer$Move back: step with the rear foot first, then drag the lead foot.$boxer$, $boxer$Move left: lead foot steps, rear foot follows. Move right: rear foot steps, lead foot follows.$boxer$, $boxer$Work each direction for 1 minute, then 2 minutes mixing directions on your own call.$boxer$, $boxer$Never cross your feet, never let them touch — the stance survives every step.$boxer$]::text[], $boxer$6 x 1-minute segments$boxer$, ARRAY[$boxer$The foot nearest the direction of travel always moves first$boxer$, $boxer$Small steps keep you ready to punch; big steps leave you stranded$boxer$, $boxer$Stay on the balls of your feet — flat feet can't step-drag$boxer$]::text[], ARRAY[$boxer$crossing-feet$boxer$, $boxer$flat-footed$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$pivot-clock$boxer$, $boxer$Pivot Clock Drill$boxer$, ARRAY[$boxer$Imagine a clock face on the floor; you start at 6 o'clock facing 12.$boxer$, $boxer$Pivot 45 degrees on your lead foot, letting the rear foot swing around — land balanced, guard up.$boxer$, $boxer$Work through 90 and 180 degrees, then repeat pivoting the other direction.$boxer$, $boxer$After each pivot, freeze: you should be able to throw a clean 1-2 immediately.$boxer$, $boxer$Do 2 minutes of pivots on call (partner calls the angle), then 2 minutes freestyle.$boxer$, $boxer$Small pivots for small angles; keep the lead foot as the anchor every time.$boxer$]::text[], $boxer$2 x 2-minute rounds$boxer$, ARRAY[$boxer$Pivot on the ball of the lead foot, not the heel$boxer$, $boxer$The pivot creates a new angle while keeping you in punching range$boxer$, $boxer$Head stays level through the turn — bobbing up gives away the move$boxer$]::text[], ARRAY[$boxer$no-pivot$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$lateral-line-shuffle$boxer$, $boxer$Lateral Line Shuffle$boxer$, ARRAY[$boxer$Lay a straight line of tape about 15 feet long on the floor.$boxer$, $boxer$Shuffle laterally along the line: 10 steps one way, 10 back, staying low.$boxer$, $boxer$Your feet never cross and never click together — push off the inside edge of the trailing foot.$boxer$, $boxer$Keep your guard up and eyes forward the whole time, as if tracking an opponent.$boxer$, $boxer$Do 4 lengths at moderate pace, then 4 lengths as fast as you can without crossing.$boxer$, $boxer$If your feet cross, slow down: speed without form is just bad habits faster.$boxer$]::text[], $boxer$8 lengths total$boxer$, ARRAY[$boxer$Lateral movement escapes straight punches and sets up angles$boxer$, $boxer$Crossed feet mean one trip away from the canvas$boxer$, $boxer$Stay low — standing tall to move fast is a contradiction$boxer$]::text[], ARRAY[$boxer$crossing-feet$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$in-out-jab$boxer$, $boxer$In-and-Out Jab Round$boxer$, ARRAY[$boxer$Start out of range from a heavy bag or imaginary opponent.$boxer$, $boxer$Step-drag in and land the jab as your lead foot plants; immediately step straight back out.$boxer$, $boxer$Stay on the balls of your feet through the whole round — no flat-footed resting.$boxer$, $boxer$Vary the rhythm: sometimes double-step in, sometimes feint the entry and stay out.$boxer$, $boxer$Work 3 minutes, resting only in your stance, never by standing up.$boxer$, $boxer$Final 30 seconds: every entry must end with the jab landing — no empty steps.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$In-and-out movement controls range; range controls the fight$boxer$, $boxer$The exit is as important as the entry — don't admire your jab$boxer$, $boxer$Light feet, not fast feet: efficiency beats frantic bouncing$boxer$]::text[], ARRAY[$boxer$flat-footed$boxer$, $boxer$lunging-steps$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$circle-the-bag$boxer$, $boxer$Circle the Heavy Bag$boxer$, ARRAY[$boxer$Take jab range from the heavy bag.$boxer$, $boxer$Circle the bag to your left for 90 seconds using small step-drag steps, maintaining exact range.$boxer$, $boxer$Reverse and circle right for 90 seconds — both directions must feel equal.$boxer$, $boxer$Throw a jab every third step without breaking stride or changing range.$boxer$, $boxer$If you drift too close or too far, correct with one small step — never a lunge.$boxer$, $boxer$Finish with 1 minute of circling where a partner randomly calls 'in!' and you step in with a 1-2, then resume range.$boxer$]::text[], $boxer$2 x 4-minute rounds$boxer$, ARRAY[$boxer$Circling at constant range is ring generalship in its simplest form$boxer$, $boxer$Small steps keep your weight under you; lunges hand your balance to the opponent$boxer$, $boxer$Move your feet as much when you're 'doing nothing' as when attacking$boxer$]::text[], ARRAY[$boxer$flat-footed$boxer$, $boxer$poor-distance-control$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$l-step-angles$boxer$, $boxer$L-Step Angle Creation$boxer$, ARRAY[$boxer$Face an imaginary opponent in your stance.$boxer$, $boxer$Step your lead foot out at a 45-degree angle to the side (forming the foot of the 'L'), then drag the rear foot to reset.$boxer$, $boxer$You should now be offline from where the opponent's straight punches travel, but still in range to punch.$boxer$, $boxer$Throw a 1-2 from the new angle, then L-step back to center.$boxer$, $boxer$Practice both sides for 2 minutes, then add a pivot after the L-step for sharper angles.$boxer$, $boxer$Never step straight back to escape — the L-step replaces the backward retreat.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$Angles make you hard to hit and easy to hit from — it's pure profit$boxer$, $boxer$Stepping straight back keeps you in the line of fire; stepping offline ends the exchange on your terms$boxer$, $boxer$Land in a stance after every L-step, ready to punch immediately$boxer$]::text[], ARRAY[$boxer$no-pivot$boxer$, $boxer$backing-straight-up$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$combo-then-angle$boxer$, $boxer$Combination Then Exit Angle$boxer$, ARRAY[$boxer$On the heavy bag, throw a 1-2-3 combination.$boxer$, $boxer$The instant the hook lands, pivot or L-step out to an angle — don't stand in front of the bag.$boxer$, $boxer$Reset at the new angle, throw the combination again, exit the other way.$boxer$, $boxer$Work 3 minutes; every combination must end with an exit step, no exceptions.$boxer$, $boxer$Round two: after the exit, immediately throw a counter 1-2 from the angle before resetting.$boxer$, $boxer$If you catch yourself backing straight up, stop the round and restart it.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Finishing a combination in front of your opponent is volunteering for the counter$boxer$, $boxer$The exit step is part of the combination — drill it like one$boxer$, $boxer$Angles after punching turn defense into your next offense$boxer$]::text[], ARRAY[$boxer$no-exit-after-combo$boxer$, $boxer$backing-straight-up$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$cut-the-ring$boxer$, $boxer$Cut the Ring (Partner)$boxer$, ARRAY[$boxer$You and a partner move in an open space; the partner tries to circle away, you try to stay in front of them.$boxer$, $boxer$Use small step-drag steps to cut off their escape — step to where they're going, not where they are.$boxer$, $boxer$Never lunge or chase with big steps; if you lunge, the partner gets a free pass for 10 seconds.$boxer$, $boxer$Keep your guard up and stay in stance the whole time — you're hunting, not running.$boxer$, $boxer$Switch roles every 2 minutes for 3 rounds each.$boxer$, $boxer$The goal is to corner the partner using footwork alone, no punches.$boxer$]::text[], $boxer$3 x 2-minute rounds each$boxer$, ARRAY[$boxer$Cutting the ring is geometry: shrink their space with each step$boxer$, $boxer$Lunging after a mover wastes energy and leaves you off balance when they turn$boxer$, $boxer$Stay patient — the ring gets smaller on its own if your steps are disciplined$boxer$]::text[], ARRAY[$boxer$lunging-steps$boxer$, $boxer$poor-distance-control$boxer$]::text[], $boxer$advanced$boxer$, $boxer$none$boxer$, $boxer$footwork$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$slip-rope-ladder$boxer$, $boxer$Slip Rope Weave$boxer$, ARRAY[$boxer$Tie a rope (or hand wraps knotted together) between two points at about shoulder height.$boxer$, $boxer$Stand at one end in your stance; roll under the rope by bending your knees and dipping your head to the side.$boxer$, $boxer$Come back up on the other side with your hands still at your cheeks.$boxer$, $boxer$Walk the length of the rope, rolling under it every step — down on one side, up on the other.$boxer$, $boxer$Add a jab before each roll: jab, roll under, come up, jab again.$boxer$, $boxer$Work the rope for 3 minutes; your legs should burn — that's the point.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Rolls come from the knees, not from bending at the waist$boxer$, $boxer$Hands stay home through the entire roll — dropping them is the classic error$boxer$, $boxer$Moving head + moving feet together is what makes defense real$boxer$]::text[], ARRAY[$boxer$no-head-movement$boxer$]::text[], $boxer$beginner$boxer$, $boxer$slip-rope$boxer$, $boxer$head-movement$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$mirror-slip-check$boxer$, $boxer$Mirror Slip Technique Check$boxer$, ARRAY[$boxer$Face a mirror in your stance.$boxer$, $boxer$Slip to your left: shift your head about 6 inches off center, bending slightly at the knees and waist together.$boxer$, $boxer$Return to center, then slip right the same way. Watch that your eyes stay level — no dipping or rising.$boxer$, $boxer$Add variety: slip left, slip right, roll under — never the same move twice in a row.$boxer$, $boxer$Do 2 minutes slow and precise, then 1 minute at speed while keeping the movement small.$boxer$, $boxer$If your head moves more than a few inches, you're over-slipping and wasting motion.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$A slip moves the head just off the punch's path — inches, not feet$boxer$, $boxer$Predictable head movement (same rhythm every time) gets timed and punished$boxer$, $boxer$Weight stays centered; reaching with the slip is just falling with style$boxer$]::text[], ARRAY[$boxer$no-head-movement$boxer$, $boxer$predictable-head-movement$boxer$]::text[], $boxer$beginner$boxer$, $boxer$mirror$boxer$, $boxer$head-movement$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$jab-slip-cross$boxer$, $boxer$Jab, Slip, Cross$boxer$, ARRAY[$boxer$Shadowbox the sequence: throw the jab, slip outside (to your left for orthodox), then throw the cross.$boxer$, $boxer$The slip must come from a small knee bend and torso shift — your head goes offline while your feet stay planted.$boxer$, $boxer$Return from the slip directly into the cross; the rotation of the slip loads the cross.$boxer$, $boxer$Do 2 minutes slow, grooving the rhythm: punch — move — punch.$boxer$, $boxer$Next 2 minutes: alternate slipping inside and outside after the jab, cross follows each.$boxer$, $boxer$Final minute at full speed — the slip must stay small even when you're moving fast.$boxer$]::text[], $boxer$3 x 2-minute rounds (with 1-min speed finisher)$boxer$, ARRAY[$boxer$Defense between punches is what separates combinations from arm-flailing$boxer$, $boxer$The slip loads your hips for the cross — defense becomes offense$boxer$, $boxer$Keep the rear hand on your cheek through the slip; it's your insurance$boxer$]::text[], ARRAY[$boxer$no-head-movement$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$head-movement$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$pull-counter-control$boxer$, $boxer$Controlled Pull Counter$boxer$, ARRAY[$boxer$In your stance, practice the pull: shift your weight onto your rear foot, letting your head drift back just out of range.$boxer$, $boxer$The movement is small — a few inches — chin tucked, eyes forward, guard intact.$boxer$, $boxer$The instant your weight settles back, fire the cross counter off the rear foot.$boxer$, $boxer$Do 10 slow reps in the mirror, checking that you never lean past your balance point.$boxer$, $boxer$With a partner throwing slow jabs, pull and counter for 2-minute rounds.$boxer$, $boxer$If you feel yourself falling backward, the pull is too big — shrink it.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$The pull is a weight shift, not a lean — leaning back is a balance disaster$boxer$, $boxer$Counter immediately; a pull without a counter is just retreating$boxer$, $boxer$This is an advanced timing move — master the slip first$boxer$]::text[], ARRAY[$boxer$excessive-lean-back$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$head-movement$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$roll-the-hook$boxer$, $boxer$Roll Under the Hook$boxer$, ARRAY[$boxer$A partner throws slow lead hooks at your head (gloves on, controlled).$boxer$, $boxer$As the hook comes, bend your knees and roll your head under and slightly to the side of the punch.$boxer$, $boxer$Your hands stay at your cheeks through the entire roll.$boxer$, $boxer$Come up on the other side already punching — the roll ends in your counter.$boxer$, $boxer$Start at quarter speed for 2 minutes, then half speed; never go full speed in this drill.$boxer$, $boxer$Switch sides so you practice rolling both directions.$boxer$]::text[], $boxer$4 x 2-minute rounds$boxer$, ARRAY[$boxer$Roll under hooks, never straight punches — rolling into a cross is a classic knockout$boxer$, $boxer$Don't roll too low; stay coiled and ready to spring up punching$boxer$, $boxer$The counter is the point of the roll — defense that doesn't lead to offense is just surviving$boxer$]::text[], ARRAY[$boxer$no-head-movement$boxer$]::text[], $boxer$advanced$boxer$, $boxer$none$boxer$, $boxer$head-movement$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$static-balance-block$boxer$, $boxer$Static Balance Block Test$boxer$, ARRAY[$boxer$Take your stance; a partner faces you wearing gloves.$boxer$, $boxer$The partner throws one slow punch at a time — first open-hand taps to your shoulders, then light straight punches.$boxer$, $boxer$Block each one from your stance: gloves to the head shots, elbows to the body shots.$boxer$, $boxer$The goal is balance, not speed — don't get pushed over, don't step, don't lean.$boxer$, $boxer$Start with one punch every 5 seconds; as you stabilize, go to one every 3 seconds.$boxer$, $boxer$Harder version: throw any punch and hold it out while the partner taps your exposed side — stay rooted.$boxer$]::text[], $boxer$4 x 2-minute rounds$boxer$, ARRAY[$boxer$This tests whether you can stand properly before it tests your defense$boxer$, $boxer$Block by recovering your gloves to position, not by chasing the punch$boxer$, $boxer$Exhale sharply on each block — breath and a slight brace repel the impact$boxer$]::text[], ARRAY[$boxer$hands-low$boxer$, $boxer$stance-drifts$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$defense$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$outside-parry-jab$boxer$, $boxer$Outside Parry Against the Jab$boxer$, ARRAY[$boxer$A partner throws slow, steady jabs at your head.$boxer$, $boxer$With your lead hand, tap the jab slightly aside — a small redirect, not a slap.$boxer$, $boxer$The motion is inches: deflect the punch off its line while your rear hand stays glued to your cheek.$boxer$, $boxer$Parry and immediately return the lead hand to guard — don't leave it hanging out.$boxer$, $boxer$Do 2 minutes parrying only, then 2 minutes where you parry and fire an immediate jab back.$boxer$, $boxer$Keep the parry minimal; big parries open your guard wider than the punch would have.$boxer$]::text[], $boxer$2 x 2-minute rounds (+ 2-min counter version)$boxer$, ARRAY[$boxer$Parries work best against long straight punches — that's their designed purpose$boxer$, $boxer$Small deflection, instant return — the parry is a detour, not a destination$boxer$, $boxer$Chin stays down through the parry; lifting it to watch is a common mistake$boxer$]::text[], ARRAY[$boxer$no-parry$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$defense$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$high-guard-catch$boxer$, $boxer$High Guard Catch Round$boxer$, ARRAY[$boxer$Take a tight high guard: gloves at your forehead, elbows in, chin down, eyes open.$boxer$, $boxer$A partner throws slow 1-2 combinations at your head; catch them on your gloves and forearms.$boxer$, $boxer$Don't flinch, don't look away, don't hold your breath — absorb calmly.$boxer$, $boxer$Between combinations, the partner feints — don't react to feints, only to real punches.$boxer$, $boxer$Work 2-minute rounds; the partner gradually increases speed as your composure holds.$boxer$, $boxer$Final round: after each caught combination, fire back a 1-2 of your own.$boxer$]::text[], $boxer$3 x 2-minute rounds$boxer$, ARRAY[$boxer$Blocking is the easiest defense to learn — master it before fancy head movement$boxer$, $boxer$Eyes open and breathing: panic is what makes people turn away$boxer$, $boxer$A caught punch is a counter opportunity — the partner's hands are busy$boxer$]::text[], ARRAY[$boxer$hands-low$boxer$, $boxer$dropping-hands-under-pressure$boxer$]::text[], $boxer$beginner$boxer$, $boxer$none$boxer$, $boxer$defense$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$floor-to-ceiling-defense$boxer$, $boxer$Floor-to-Ceiling Bag Defense$boxer$, ARRAY[$boxer$Stand in front of a floor-to-ceiling (double-end style rebound) bag.$boxer$, $boxer$Throw a single jab; the bag rebounds toward your face — slip, parry, or block it.$boxer$, $boxer$You may not throw your next punch until you've defended the rebound.$boxer$, $boxer$Start with single punches, then build to 1-2s, defending after every combination.$boxer$, $boxer$The bag's return is unpredictable — that's the point; react, don't anticipate.$boxer$, $boxer$Work 3-minute rounds; count how many rebounds touch you and drive the number down.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$This bag teaches the punch-defense-punch rhythm that defines real exchanges$boxer$, $boxer$Defend first, punch second — reversing that order is how you get caught$boxer$, $boxer$Keep the defensive motion small; the bag is fast and big motions won't catch up$boxer$]::text[], ARRAY[$boxer$no-head-movement$boxer$, $boxer$no-parry$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$defense$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$defense-only-round$boxer$, $boxer$Defense-Only Sparring Round$boxer$, ARRAY[$boxer$Light, controlled partner work: the partner attacks at about half speed and power.$boxer$, $boxer$You may not throw a single punch — only block, parry, slip, roll, and move your feet.$boxer$, $boxer$Survive 2-minute rounds purely on defense, staying calm and balanced.$boxer$, $boxer$Focus on one defensive tool per round: round one blocks only, round two slips and rolls, round three anything.$boxer$, $boxer$The partner should tell you afterward which defense you relied on most and which felt shakiest.$boxer$, $boxer$Build to 3-minute rounds; composure under fire is the skill being trained.$boxer$]::text[], $boxer$3 x 2-minute rounds (build to 3 min)$boxer$, ARRAY[$boxer$Removing offense forces your defense to actually work — no hiding behind punching$boxer$, $boxer$Stay relaxed; tension slows every defensive reaction$boxer$, $boxer$Footwork is defense too — stepping out of range counts and it's often the best option$boxer$]::text[], ARRAY[$boxer$static-defense$boxer$, $boxer$dropping-hands-under-pressure$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$defense$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$block-to-counter$boxer$, $boxer$Block-to-Counter on the Mitts$boxer$, ARRAY[$boxer$A partner holds mitts and feeds you slow jab-cross combinations.$boxer$, $boxer$Block or parry each punch, then fire the immediate counter the mitt holder presents.$boxer$, $boxer$The counter must come instantly — defense and offense are one beat, not two.$boxer$, $boxer$Start with scripted counters (block jab, counter cross), then let the holder call them live.$boxer$, $boxer$Work 3-minute rounds; the holder increases speed as your counters stay sharp.$boxer$, $boxer$Every defensive motion should load the counter: the block's rotation feeds the punch.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$A defense that doesn't create offense is just delaying the inevitable$boxer$, $boxer$The fastest counter is the one your defensive motion already started$boxer$, $boxer$Stay in range through the defense — running away wastes the opening you earned$boxer$]::text[], ARRAY[$boxer$static-defense$boxer$, $boxer$no-parry$boxer$]::text[], $boxer$advanced$boxer$, $boxer$mitts$boxer$, $boxer$defense$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$shoulder-roll-intro$boxer$, $boxer$Shoulder Roll Introduction (Advanced)$boxer$, ARRAY[$boxer$Note: this is an advanced technique for experienced boxers — master the basic guard first.$boxer$, $boxer$In your stance, raise your lead shoulder high, tuck your chin behind it, rear hand at your cheek.$boxer$, $boxer$Practice the rolling motion slowly in a mirror: rotate the shoulder to deflect an imaginary straight punch.$boxer$, $boxer$The punch should glance off the deltoid, not land flush — angle, not absorption.$boxer$, $boxer$Have a partner throw very slow straight punches while you roll them off the shoulder.$boxer$, $boxer$Never use this at close range or against hooks until a coach clears you — it has real limitations.$boxer$]::text[], $boxer$3 x 2-minute slow rounds$boxer$, ARRAY[$boxer$The shoulder roll suits certain body types and styles — it's not for everyone$boxer$, $boxer$It fails against tight hooks and at clinch range; know its limits$boxer$, $boxer$Hands stay free to counter — that's the technique's entire payoff$boxer$]::text[], ARRAY[$boxer$static-defense$boxer$]::text[], $boxer$advanced$boxer$, $boxer$none$boxer$, $boxer$defense$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$one-two-metronome$boxer$, $boxer$1-2 Metronome (Heavy Bag)$boxer$, ARRAY[$boxer$Work the heavy bag for a 3-minute round throwing nothing but the jab-cross.$boxer$, $boxer$Keep an even rhythm — like a metronome — with full snap and full return on every punch.$boxer$, $boxer$Every jab sets up the cross; every cross is thrown with hip rotation and a pivoted rear foot.$boxer$, $boxer$Between combinations, bounce lightly in your stance — never flat-footed, never admiring the bag.$boxer$, $boxer$Round two: vary the rhythm — double up the jab sometimes (1-1-2), pause sometimes — but only 1s and 2s.$boxer$, $boxer$Count your clean 1-2s per round; the number should rise as the motion gets automatic.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$The 1-2 is the foundation every longer combination is built from — it must be automatic$boxer$, $boxer$Even rhythm first, broken rhythm later; chaos without fundamentals is just flailing$boxer$, $boxer$Both punches return to guard — the combination isn't done until the hands are home$boxer$]::text[], ARRAY[$boxer$single-punches-only$boxer$]::text[], $boxer$beginner$boxer$, $boxer$bag$boxer$, $boxer$combinations$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$one-two-hook-build$boxer$, $boxer$1-2-3 Builder (Heavy Bag)$boxer$, ARRAY[$boxer$On the heavy bag, throw the 1-2, then add the lead hook: jab-cross-hook.$boxer$, $boxer$The hook pivots the lead foot with a 90-degree elbow — the same geometry from the mirror drill.$boxer$, $boxer$Throw the three punches as one flowing motion, not three separate punches.$boxer$, $boxer$After the hook, snap back to guard before anything else.$boxer$, $boxer$Work 3 minutes, then add a final cross: 1-2-3-2 for the last minute of each round.$boxer$, $boxer$If the hook gets loopy when you're tired, slow down — the arc must stay tight.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Straight punches then a hook is the classic head-target combination — learn its feel$boxer$, $boxer$The hook's rotation is the same hip turn as the cross, just redirected$boxer$, $boxer$Flow matters more than power; speed comes from relaxation between punches$boxer$]::text[], ARRAY[$boxer$single-punches-only$boxer$, $boxer$no-hip-rotation$boxer$]::text[], $boxer$beginner$boxer$, $boxer$bag$boxer$, $boxer$combinations$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$head-body-level-change$boxer$, $boxer$Head-Body Level Change (Heavy Bag)$boxer$, ARRAY[$boxer$On the heavy bag, throw a 1-2 to the head, then drop your level and throw a 1-2 to the body.$boxer$, $boxer$The level change comes from bending your knees — never from reaching down or bowing at the waist.$boxer$, $boxer$Alternate head and body every combination for the full round.$boxer$, $boxer$Keep your eyes up and chin tucked even when punching low — the head stays protected.$boxer$, $boxer$Round two: mix it — 1-2 head then hook to the body, or double jab body then cross head.$boxer$, $boxer$Finish each round with 30 seconds of free head-body mixing at speed.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Body punches make opponents drop their hands — then the head is open$boxer$, $boxer$Bend the knees to change levels; the spine angle barely changes$boxer$, $boxer$Never admire body work with your head down — come back up behind your guard$boxer$]::text[], ARRAY[$boxer$no-level-changes$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$combinations$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$jab-body-cross-head$boxer$, $boxer$Jab to Body, Cross to Head$boxer$, ARRAY[$boxer$Step in with a level change and drive the jab into the bag's midsection.$boxer$, $boxer$Come up off the jab and fire the cross to the head in one continuous motion.$boxer$, $boxer$The combination is down-up: body shot drops the guard, head shot exploits it.$boxer$, $boxer$Keep the rear hand at your cheek during the body jab — you're bent, not open.$boxer$, $boxer$Work 3 minutes alternating with the reverse: jab head, cross body.$boxer$, $boxer$Add footwork in round three: step in with the combo, pivot out after.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$High-low combinations are among the highest-percentage sequences in boxing$boxer$, $boxer$The level change must be quick — lingering low is dangerous$boxer$, $boxer$Sell the body shot with your knees so the head shot lands clean$boxer$]::text[], ARRAY[$boxer$no-level-changes$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$combinations$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$combo-exit-jab$boxer$, $boxer$Combination Exit Jab (Mitts)$boxer$, ARRAY[$boxer$A partner holds mitts; throw any 3-punch combination they call.$boxer$, $boxer$The instant the last punch lands, throw an exit jab while stepping out at an angle.$boxer$, $boxer$The exit jab doesn't need power — its job is to cover your exit and reset range.$boxer$, $boxer$Never finish a combination standing in the pocket; the exit is mandatory.$boxer$, $boxer$The holder occasionally throws a counter mitt at you after your combo — the exit jab must beat it.$boxer$, $boxer$Work 3-minute rounds, varying the combinations; the exit stays constant.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Most beginners get hit after their own combinations, not during them$boxer$, $boxer$The exit jab buys safe distance while keeping you offensively engaged$boxer$, $boxer$Angle out, never straight back — the footwork drills built this habit$boxer$]::text[], ARRAY[$boxer$no-exit-after-combo$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$mitts$boxer$, $boxer$combinations$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$championship-rounds-bag$boxer$, $boxer$Championship Rounds (Heavy Bag)$boxer$, ARRAY[$boxer$Three 3-minute heavy bag rounds with 1-minute rests — full fight simulation.$boxer$, $boxer$Combinations only: no single punches allowed for the entire drill.$boxer$, $boxer$Pace yourself like a real fight: busy first round, measured second, everything left in the third.$boxer$, $boxer$In the last 30 seconds of each round, empty the tank — then check: is your guard still up?$boxer$, $boxer$Between rounds, hands stay up while you breathe; dropping them in the rest is a habit, not recovery.$boxer$, $boxer$Score each round: clean combinations landed vs. times your guard dropped from fatigue.$boxer$]::text[], $boxer$3 x 3-minute rounds$boxer$, ARRAY[$boxer$Technique under fatigue is the real test — anyone looks good fresh$boxer$, $boxer$The guard must survive the round, not just start it$boxer$, $boxer$Pace with your breathing: exhale on every punch, never hold your breath in a flurry$boxer$]::text[], ARRAY[$boxer$hands-drop-when-tired$boxer$, $boxer$gassing-late$boxer$]::text[], $boxer$advanced$boxer$, $boxer$bag$boxer$, $boxer$combinations$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$rope-rounds$boxer$, $boxer$Jump Rope Rounds$boxer$, ARRAY[$boxer$Jump rope for 3-minute rounds with 1-minute rests, matching boxing round timing.$boxer$, $boxer$Stay on the balls of your feet with small, quiet jumps — barely leaving the ground.$boxer$, $boxer$Keep your shoulders relaxed and turn the rope with your wrists, not your arms.$boxer$, $boxer$Alternate 1 minute basic bounce, 1 minute boxer's step (shifting weight side to side), 1 minute high knees.$boxer$, $boxer$Build from 3 rounds to 6 over several weeks.$boxer$, $boxer$If you trip, restart the jump immediately — recovering rhythm fast is part of the training.$boxer$]::text[], $boxer$3-6 x 3-minute rounds$boxer$, ARRAY[$boxer$Rope work builds the calf endurance and rhythm that footwork runs on$boxer$, $boxer$Relaxed shoulders: tension in the rope becomes tension in your punches$boxer$, $boxer$Boxing conditioning is interval-based — train in rounds, not in miles$boxer$]::text[], ARRAY[$boxer$gassing-late$boxer$, $boxer$slow-recovery$boxer$]::text[], $boxer$beginner$boxer$, $boxer$rope$boxer$, $boxer$conditioning$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$bag-sprint-intervals$boxer$, $boxer$Heavy Bag Sprint Intervals$boxer$, ARRAY[$boxer$Set an interval timer: 20 seconds all-out, 40 seconds easy, for 8 cycles.$boxer$, $boxer$During the 20-second bursts, throw non-stop flurries at the heavy bag — maximum output.$boxer$, $boxer$During the 40-second recovery, bounce lightly in your stance and breathe — hands stay up.$boxer$, $boxer$Keep punching form honest during the bursts; sloppy tired punches injure wrists.$boxer$, $boxer$Rest 2 minutes, then do a second block of 8 if your form survived the first.$boxer$, $boxer$Track your punch count per burst; the goal is maintaining output across all 8.$boxer$]::text[], $boxer$8 x (20s on / 40s off), 1-2 blocks$boxer$, ARRAY[$boxer$Fights are won in bursts — train the burst and the recovery between them$boxer$, $boxer$The easy intervals are active: stance, bounce, breathe, guard up$boxer$, $boxer$If your output collapses by round 5, your pacing needs work, not just your fitness$boxer$]::text[], ARRAY[$boxer$gassing-late$boxer$, $boxer$slow-recovery$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$bag$boxer$, $boxer$conditioning$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$roadwork-fartlek$boxer$, $boxer$Fartlek Roadwork$boxer$, ARRAY[$boxer$Run for 30 minutes total on a route with some variation (hills ideal, flat fine).$boxer$, $boxer$Alternate 2 minutes easy jogging with 1 minute of hard pickups — sprint the pickups.$boxer$, $boxer$During easy sections, practice boxing breathing: rhythmic exhales, relaxed shoulders.$boxer$, $boxer$During pickups, drive with your arms as if pumping punches — running form feeds fighting form.$boxer$, $boxer$Finish the last 5 minutes with 30-second sprint / 30-second jog alternations.$boxer$, $boxer$Cool down with 5 minutes of walking; stretch at the gym, not immediately after.$boxer$]::text[], $boxer$30 minutes (2 min easy / 1 min hard)$boxer$, ARRAY[$boxer$Boxing is an interval sport — fartlek running matches its energy demands better than steady jogging$boxer$, $boxer$Keep roadwork moderate in volume; excessive long slow distance can blunt punching power$boxer$, $boxer$Consistency beats heroics: regular 30-minute sessions over occasional epics$boxer$]::text[], ARRAY[$boxer$gassing-late$boxer$, $boxer$slow-recovery$boxer$]::text[], $boxer$intermediate$boxer$, $boxer$none$boxer$, $boxer$conditioning$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
insert into public.drills (id,title,instructions,sets_reps,coaching_points,targets_faults,difficulty,equipment,category) values ($boxer$fatigue-technique-round$boxer$, $boxer$Technique Under Fatigue$boxer$, ARRAY[$boxer$Do a hard conditioning burst first: 2 minutes of burpees, mountain climbers, or all-out bag flurries.$boxer$, $boxer$Immediately — no rest — shadowbox for 2 minutes focusing purely on technique.$boxer$, $boxer$Throw clean 1-2s, hooks with proper rotation, and keep your guard perfect despite the fatigue.$boxer$, $boxer$Have a partner (or camera) watch specifically for: dropping hands, arm punches, and stance widening.$boxer$, $boxer$Rest 1 minute, then repeat the whole sequence twice more.$boxer$, $boxer$The drill is passed when your third-round technique looks like your first.$boxer$]::text[], $boxer$3 x (2-min burst + 2-min technique)$boxer$, ARRAY[$boxer$Fights are decided late when technique degrades — this trains technique to survive$boxer$, $boxer$Fatigue exposes your true habits; whatever breaks here is what needs drilling fresh$boxer$, $boxer$Slow down before you get sloppy — clean slow beats fast and broken$boxer$]::text[], ARRAY[$boxer$hands-drop-when-tired$boxer$, $boxer$arm-punching$boxer$]::text[], $boxer$advanced$boxer$, $boxer$none$boxer$, $boxer$conditioning$boxer$)
  on conflict (id) do update set title=excluded.title, instructions=excluded.instructions, sets_reps=excluded.sets_reps, coaching_points=excluded.coaching_points, targets_faults=excluded.targets_faults, difficulty=excluded.difficulty, equipment=excluded.equipment, category=excluded.category;
